// 深化記事の本文は複数のブロック種別で構成できる。
// 既存記事は section.body（string[]）のまま動作する後方互換のユニオン型。
export type GuideBlock =
  | { type: "p"; text: string }
  | { type: "table"; headers: string[]; rows: string[][]; caption?: string }
  | { type: "svg"; svg: string; caption?: string }
  | { type: "faq"; items: { q: string; a: string }[] }
  | { type: "refs"; items: { label: string; url: string; note?: string }[] };

export type GuideSection = {
  heading: string;
  // 旧形式（段落の配列）。既存12記事はこちらを使用。
  body?: string[];
  // 新形式（表・図・FAQ・参考情報を含むブロック配列）。深化記事で使用。
  blocks?: GuideBlock[];
};

export type GuideArticle = {
  slug: string;
  title: string;
  description: string;
  // 記事冒頭のリード文（深化記事のみ。未設定なら description を代用）
  lead?: string;
  readingTime: string;
  category: string;
  // 実際の初公開日
  published: string;
  // 最終更新日
  updated: string;
  sections: GuideSection[];
};

